-- =============================================================================
-- University of Nigeria, Nsukka -- populate the real syllabus content for
-- GST 211, GST 212, GST 311 and GST 312 (the courses renamed from
-- GSP 207/208/201/202). The rename migration only changed course_code;
-- description/topics still held whatever each department had before, which
-- is why the user's own GST course-outline upload from this same document
-- wasn't visibly reflected in the app. This migration fills in the actual
-- official content from the GST course circular (new CCMAS curriculum) the
-- user supplied, applied uniformly across every department, since these are
-- centrally-defined General Studies courses with one official syllabus
-- (not department-authored like a major course).
-- =============================================================================

update public.course_outlines
   set description = 'Scope of philosophy: notions, meanings, branches and problems of philosophy. Logic as an indispensable tool of philosophy. Elements of syllogism, symbolic logic -- the first nine rules of inference. Fallacies, laws of thought, nature of arguments. Valid and invalid arguments, logic of form and logic of content -- deductive induction and inferences. Creative and critical thinking. Impact of philosophy on human existence, philosophy and politics, philosophy and religion, philosophy and human values, philosophy of human conduct, philosophy and character molding.',
       topics = '["Scope of philosophy: notions, meanings, branches and problems of philosophy", "Logic as an indispensable tool of philosophy", "Elements of syllogism, symbolic logic -- the first nine rules of inference", "Fallacies, laws of thought, nature of arguments", "Valid and invalid arguments, logic of form and logic of content -- deductive induction and inferences", "Creative and critical thinking", "Impact of philosophy on human existence, philosophy and politics, philosophy and religion, philosophy and human values, philosophy of human conduct, philosophy and character molding"]'::jsonb
 where institution = 'University of Nigeria, Nsukka'
   and course_code = 'GST 211';

update public.course_outlines
   set description = 'Nigerian history, culture and art up to 1800 (Yoruba, Hausa and Igbo peoples). Peoples and cultures of the ethnic minority groups. Nigeria under colonial rule -- advent and administration of colonial rule in Nigeria. Evolution of Nigeria as a political unit (amalgamation of Nigeria in 1914). Formation of political parties in Nigeria. Nationalist movement and struggle for independence. Nigeria and challenges of nation building -- military intervention in Nigerian politics, the Nigerian Civil War, etc. Concept and economics of self-reliance -- indigenous trade and market system, indigenous apprenticeship system among Nigerian people, trade, skill acquisition and self-reliance. Social justice and national development -- law, definition and classification, judiciary and fundamental rights. The individual, norms and values -- basic Nigerian norms and values, patterns of citizenship acquisition, citizenship and civic responsibilities, indigenous languages, usage and development. Negative attitudes and other related social vices. Cultism, kidnapping and other national values -- the 3R''s (Reconstruction, Rehabilitation, Re-orientation), re-orientation strategies (Operation Feed the Nation, War Against Indiscipline, War Against Austerity Measures, Mass Mobilization for Self-Reliance, Social Justice and Economic Recovery, National Orientation Agency). Current socio-political and cultural developments in Nigeria.',
       topics = '["Nigerian history, culture and art up to 1800 (Yoruba, Hausa and Igbo peoples)", "Peoples and cultures of the ethnic minority groups", "Nigeria under colonial rule: advent and administration of colonial rule", "Evolution of Nigeria as a political unit (amalgamation of Nigeria in 1914)", "Formation of political parties in Nigeria", "Nationalist movement and struggle for independence", "Nigeria and challenges of nation building: military intervention in Nigerian politics, the Nigerian Civil War", "Concept and economics of self-reliance: indigenous trade and market system, apprenticeship, skill acquisition", "Social justice and national development: law, judiciary and fundamental rights", "The individual, norms and values: citizenship acquisition, civic responsibilities, indigenous languages", "Negative attitudes and other related social vices", "Cultism, kidnapping and national re-orientation strategies (OFN, WAI, MAMSER, NOA)", "Current socio-political and cultural developments in Nigeria"]'::jsonb
 where institution = 'University of Nigeria, Nsukka'
   and course_code = 'GST 212';

update public.course_outlines
   set description = 'Basic concepts in peace studies and conflict resolution. History and evolution of peace and conflict studies. Types and nature of social conflict. Theories of social conflict. Elements of peace studies and conflict resolution. Root causes of conflict and violence in Africa. Conflict and security in a multi-ethnic nation. Selected conflict case studies -- Tiv-Jukun; Zangon Kataf, Ife-Modakeke; Otuocha-Aguleri/Izzi-Ezangbo; chieftaincy and land disputes and many others. Geography and environmental security. Legal framework for social justice and conflict resolution in Nigeria. Conflict resolution strategies in traditional societies: lessons for the present. Alternative Dispute Resolution (ADR) mechanisms and procedure.',
       topics = '["Basic concepts in peace studies and conflict resolution", "History and evolution of peace and conflict studies", "Types and nature of social conflict", "Theories of social conflict", "Elements of peace studies and conflict resolution", "Root causes of conflict and violence in Africa", "Conflict and security in a multi-ethnic nation", "Selected conflict case studies: Tiv-Jukun, Zangon Kataf, Ife-Modakeke, Otuocha-Aguleri/Izzi-Ezangbo, chieftaincy and land disputes", "Geography and environmental security", "Legal framework for social justice and conflict resolution in Nigeria", "Conflict resolution strategies in traditional societies: lessons for the present", "Alternative Dispute Resolution (ADR) mechanisms and procedure"]'::jsonb
 where institution = 'University of Nigeria, Nsukka'
   and course_code = 'GST 311';

update public.course_outlines
   set description = 'Emerging issues in peace and conflict studies. Conflict analysis and conflict handling styles. Approaches to conflict resolution, conflict management and peacebuilding. Terrorism, banditry, separatism, insurgencies and natural resource conflicts. Health and health-related conflicts. Peace education and human rights education. The role of civil society and community-based organizations in conflict resolution. The media, conflict, conflict transformation and peacebuilding. Community policing: evolution and imperatives. The role of international organizations in conflict resolution -- ECOWAS, AU, UN. Managing post-conflict situations/crisis -- refugees, internally displaced persons (IDPs). The role of NGOs in post-conflict peacebuilding. Conflict simulations/conflict scenario building.',
       topics = '["Emerging issues in peace and conflict studies", "Conflict analysis and conflict handling styles", "Approaches to conflict resolution, conflict management and peacebuilding", "Terrorism, banditry, separatism, insurgencies and natural resource conflicts", "Health and health-related conflicts", "Peace education and human rights education", "The role of civil society and community-based organizations in conflict resolution", "The media, conflict, conflict transformation and peacebuilding", "Community policing: evolution and imperatives", "The role of international organizations in conflict resolution: ECOWAS, AU, UN", "Managing post-conflict situations/crisis: refugees, internally displaced persons (IDPs)", "The role of NGOs in post-conflict peacebuilding", "Conflict simulations/conflict scenario building"]'::jsonb
 where institution = 'University of Nigeria, Nsukka'
   and course_code = 'GST 312';
